insert into public.message_templates (name, language, category, body, variables, buttons) values
  ('rf_welcome', 'bn', 'UTILITY', E'{{1}}-এ স্বাগতম, {{2}}! 🏠 আপনি রুম {{3}}, বেড {{4}}-এর জন্য নিবন্ধিত। আপনার বিল ও রসিদ এই নম্বরে আসবে। এর জন্য {{1}} ও RentFlow আপনার নাম, ফোন ও থাকার বিবরণ রাখে। এগিয়ে যেতে *আমি রাজি* চাপুন।', 4, E'["আমি রাজি","মেনু"]'),
  ('rf_welcome', 'mr', 'UTILITY', E'{{1}} मध्ये स्वागत आहे, {{2}}! 🏠 तुमची नोंदणी खोली {{3}}, बेड {{4}} साठी झाली आहे. तुमची बिले आणि पावत्या याच नंबरवर येतील. यासाठी {{1}} आणि RentFlow तुमचे नाव, फोन आणि राहण्याचा तपशील ठेवतात. पुढे जाण्यासाठी *मी सहमत आहे* दाबा.', 4, E'["मी सहमत आहे","मेनू"]'),
  ('rf_welcome', 'te', 'UTILITY', E'{{1}}కు స్వాగతం, {{2}}! 🏠 మీరు గది {{3}}, బెడ్ {{4}}కు నమోదయ్యారు. మీ బిల్లులు మరియు రసీదులు ఈ నంబర్‌కే వస్తాయి. దీని కోసం {{1}} మరియు RentFlow మీ పేరు, ఫోన్ మరియు నివాస వివరాలను భద్రపరుస్తాయి. కొనసాగడానికి *నేను అంగీకరిస్తున్నాను* నొక్కండి.', 4, E'["అంగీకరిస్తున్నాను","మెనూ"]'),
  ('rf_welcome', 'ta', 'UTILITY', E'{{1}}-க்கு வரவேற்கிறோம், {{2}}! 🏠 நீங்கள் அறை {{3}}, படுக்கை {{4}}-க்குப் பதிவு செய்யப்பட்டுள்ளீர்கள். உங்கள் பில்களும் ரசீதுகளும் இந்த எண்ணுக்கே வரும். இதற்காக {{1}} மற்றும் RentFlow உங்கள் பெயர், தொலைபேசி மற்றும் தங்கும் விவரங்களைச் சேமிக்கின்றன. தொடர *நான் ஒப்புக்கொள்கிறேன்* அழுத்துங்கள்.', 4, E'["ஒப்புக்கொள்கிறேன்","மெனு"]'),
  ('rf_welcome', 'gu', 'UTILITY', E'{{1}}માં આપનું સ્વાગત છે, {{2}}! 🏠 તમે રૂમ {{3}}, બેડ {{4}} માટે નોંધાયેલા છો. તમારાં બિલ અને રસીદો આ જ નંબર પર આવશે. આ માટે {{1}} અને RentFlow તમારું નામ, ફોન અને રહેવાની વિગત રાખે છે. આગળ વધવા *હું સંમત છું* દબાવો.', 4, E'["હું સંમત છું","મેનુ"]'),
  ('rf_welcome', 'kn', 'UTILITY', E'{{1}} ಗೆ ಸ್ವಾಗತ, {{2}}! 🏠 ನೀವು ಕೊಠಡಿ {{3}}, ಬೆಡ್ {{4}} ಗೆ ನೋಂದಣಿಯಾಗಿದ್ದೀರಿ. ನಿಮ್ಮ ಬಿಲ್‌ಗಳು ಮತ್ತು ರಸೀದಿಗಳು ಇದೇ ನಂಬರ್‌ಗೆ ಬರುತ್ತವೆ. ಇದಕ್ಕಾಗಿ {{1}} ಮತ್ತು RentFlow ನಿಮ್ಮ ಹೆಸರು, ಫೋನ್ ಮತ್ತು ವಾಸದ ವಿವರಗಳನ್ನು ಇಟ್ಟುಕೊಳ್ಳುತ್ತವೆ. ಮುಂದುವರಿಯಲು *ನಾನು ಒಪ್ಪುತ್ತೇನೆ* ಒತ್ತಿ.', 4, E'["ನಾನು ಒಪ್ಪುತ್ತೇನೆ","ಮೆನು"]'),
  ('rf_welcome', 'ml', 'UTILITY', E'{{1}}-ലേക്ക് സ്വാഗതം, {{2}}! 🏠 നിങ്ങൾ മുറി {{3}}, ബെഡ് {{4}}-ന് രജിസ്റ്റർ ചെയ്തിരിക്കുന്നു. നിങ്ങളുടെ ബില്ലുകളും രസീതുകളും ഈ നമ്പറിൽ തന്നെ വരും. ഇതിനായി {{1}}-ഉം RentFlow-ഉം നിങ്ങളുടെ പേര്, ഫോൺ, താമസ വിവരങ്ങൾ സൂക്ഷിക്കുന്നു. തുടരാൻ *ഞാൻ സമ്മതിക്കുന്നു* അമർത്തുക.', 4, E'["ഞാൻ സമ്മതിക്കുന്നു","മെനു"]'),
  ('rf_welcome', 'pa', 'UTILITY', E'{{1}} ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ, {{2}}! 🏠 ਤੁਸੀਂ ਕਮਰਾ {{3}}, ਬੈੱਡ {{4}} ਲਈ ਰਜਿਸਟਰ ਹੋ। ਤੁਹਾਡੇ ਬਿੱਲ ਅਤੇ ਰਸੀਦਾਂ ਇਸੇ ਨੰਬਰ \'ਤੇ ਆਉਣਗੀਆਂ। ਇਸ ਲਈ {{1}} ਅਤੇ RentFlow ਤੁਹਾਡਾ ਨਾਮ, ਫ਼ੋਨ ਅਤੇ ਰਹਿਣ ਦਾ ਵੇਰਵਾ ਰੱਖਦੇ ਹਨ। ਅੱਗੇ ਵਧਣ ਲਈ *ਮੈਂ ਸਹਿਮਤ ਹਾਂ* ਦਬਾਓ।', 4, E'["ਮੈਂ ਸਹਿਮਤ ਹਾਂ","ਮੀਨੂ"]'),
  ('rf_welcome', 'ur', 'UTILITY', E'{{1}} میں خوش آمدید، {{2}}! 🏠 آپ کمرہ {{3}}، بیڈ {{4}} کے لیے رجسٹرڈ ہیں۔ آپ کے بل اور رسیدیں اسی نمبر پر آئیں گی۔ اس کے لیے {{1}} اور RentFlow آپ کا نام، فون اور رہائش کی تفصیل رکھتے ہیں۔ آگے بڑھنے کے لیے *میں متفق ہوں* دبائیں۔', 4, E'["میں متفق ہوں","مینو"]'),
  ('rf_bill', 'bn', 'UTILITY', E'{{1}}: {{2}}-এর আপনার বিল তৈরি।\nমোট: {{3}}\nদেওয়ার টাকা: *{{4}}*\nশেষ তারিখ: {{5}}\n\n{{6}}\n\nএখানে পেমেন্ট করুন: {{7}}\n\n{{8}}\n\nশুধুমাত্র এই QR বা UPI ID-তেই পেমেন্ট করুন। RentFlow কখনও অন্য কাউকে টাকা দিতে বলবে না।', 8, E'["বিবরণ দেখুন"]'),
  ('rf_bill', 'mr', 'UTILITY', E'{{1}}: {{2}} चे तुमचे बिल तयार आहे.\nएकूण: {{3}}\nभरायची रक्कम: *{{4}}*\nअंतिम तारीख: {{5}}\n\n{{6}}\n\nइथे पैसे भरा: {{7}}\n\n{{8}}\n\nफक्त याच QR किंवा UPI ID वर पैसे भरा. RentFlow तुम्हाला कधीही दुसऱ्या कोणाला पैसे भरायला सांगणार नाही.', 8, E'["तपशील पाहा"]'),
  ('rf_bill', 'te', 'UTILITY', E'{{1}}: {{2}} మీ బిల్ సిద్ధంగా ఉంది.\nమొత్తం: {{3}}\nచెల్లించాల్సినది: *{{4}}*\nచివరి తేదీ: {{5}}\n\n{{6}}\n\nఇక్కడ చెల్లించండి: {{7}}\n\n{{8}}\n\nఈ QR లేదా UPI IDకి మాత్రమే చెల్లించండి. RentFlow ఎప్పుడూ వేరే ఎవరికీ చెల్లించమని అడగదు.', 8, E'["వివరాలు చూడండి"]'),
  ('rf_bill', 'ta', 'UTILITY', E'{{1}}: {{2}} உங்கள் பில் தயார்.\nமொத்தம்: {{3}}\nசெலுத்த வேண்டியது: *{{4}}*\nகடைசி தேதி: {{5}}\n\n{{6}}\n\nஇங்கே செலுத்துங்கள்: {{7}}\n\n{{8}}\n\nஇந்த QR அல்லது UPI ID-க்கு மட்டுமே செலுத்துங்கள். RentFlow ஒருபோதும் வேறு யாருக்கும் செலுத்தச் சொல்லாது.', 8, E'["விவரம் பார்"]'),
  ('rf_bill', 'gu', 'UTILITY', E'{{1}}: {{2}}નું તમારું બિલ તૈયાર છે.\nકુલ: {{3}}\nચૂકવવાની રકમ: *{{4}}*\nછેલ્લી તારીખ: {{5}}\n\n{{6}}\n\nઅહીં ચૂકવો: {{7}}\n\n{{8}}\n\nફક્ત આ QR અથવા UPI ID પર જ ચૂકવો. RentFlow ક્યારેય બીજા કોઈને ચૂકવવાનું કહેશે નહીં.', 8, E'["વિગત જુઓ"]'),
  ('rf_bill', 'kn', 'UTILITY', E'{{1}}: {{2}} ನಿಮ್ಮ ಬಿಲ್ ಸಿದ್ಧವಾಗಿದೆ.\nಒಟ್ಟು: {{3}}\nಪಾವತಿಸಬೇಕಾದ ಮೊತ್ತ: *{{4}}*\nಕೊನೆಯ ದಿನಾಂಕ: {{5}}\n\n{{6}}\n\nಇಲ್ಲಿ ಪಾವತಿಸಿ: {{7}}\n\n{{8}}\n\nಈ QR ಅಥವಾ UPI ID ಗೆ ಮಾತ್ರ ಪಾವತಿಸಿ. RentFlow ಎಂದಿಗೂ ಬೇರೆ ಯಾರಿಗೂ ಪಾವತಿಸಲು ಕೇಳುವುದಿಲ್ಲ.', 8, E'["ವಿವರ ನೋಡಿ"]'),
  ('rf_bill', 'ml', 'UTILITY', E'{{1}}: {{2}} നിങ്ങളുടെ ബിൽ തയ്യാറാണ്.\nആകെ: {{3}}\nഅടയ്ക്കേണ്ട തുക: *{{4}}*\nഅവസാന തീയതി: {{5}}\n\n{{6}}\n\nഇവിടെ അടയ്ക്കുക: {{7}}\n\n{{8}}\n\nഈ QR അല്ലെങ്കിൽ UPI ID-യിലേക്ക് മാത്രം അടയ്ക്കുക. മറ്റാർക്കെങ്കിലും പണം നൽകാൻ RentFlow ഒരിക്കലും ആവശ്യപ്പെടില്ല.', 8, E'["വിശദാംശങ്ങൾ"]'),
  ('rf_bill', 'pa', 'UTILITY', E'{{1}}: {{2}} ਦਾ ਤੁਹਾਡਾ ਬਿੱਲ ਤਿਆਰ ਹੈ।\nਕੁੱਲ: {{3}}\nਭੁਗਤਾਨ ਰਕਮ: *{{4}}*\nਆਖਰੀ ਤਾਰੀਖ: {{5}}\n\n{{6}}\n\nਇੱਥੇ ਭੁਗਤਾਨ ਕਰੋ: {{7}}\n\n{{8}}\n\nਸਿਰਫ਼ ਇਸੇ QR ਜਾਂ UPI ID \'ਤੇ ਭੁਗਤਾਨ ਕਰੋ। RentFlow ਕਦੇ ਵੀ ਕਿਸੇ ਹੋਰ ਨੂੰ ਭੁਗਤਾਨ ਕਰਨ ਲਈ ਨਹੀਂ ਕਹੇਗਾ।', 8, E'["ਵੇਰਵਾ ਵੇਖੋ"]'),
  ('rf_bill', 'ur', 'UTILITY', E'{{1}}: {{2}} کا آپ کا بل تیار ہے۔\nکل: {{3}}\nادائیگی کی رقم: *{{4}}*\nآخری تاریخ: {{5}}\n\n{{6}}\n\nیہاں ادا کریں: {{7}}\n\n{{8}}\n\nصرف اسی QR یا UPI ID پر ادائیگی کریں۔ RentFlow آپ سے کبھی کسی اور کو ادائیگی کرنے کو نہیں کہے گا۔', 8, E'["تفصیل دیکھیں"]'),
  ('rf_reminder', 'bn', 'UTILITY', E'{{1}}: মনে করিয়ে দিচ্ছি — {{3}}-এর আপনার ভাড়া *{{2}}* {{4}}। {{5}}\n\nপেমেন্ট করতে *এখনই পেমেন্ট* চাপুন। পেমেন্ট করে থাকলে এই বার্তাটি উপেক্ষা করুন।', 5, E'[]'),
  ('rf_reminder', 'mr', 'UTILITY', E'{{1}}: आठवण — {{3}} चे तुमचे भाडे *{{2}}* {{4}}. {{5}}\n\nपैसे भरण्यासाठी *आता पैसे भरा* दाबा. आधीच भरले असल्यास हा संदेश दुर्लक्षित करा.', 5, E'[]'),
  ('rf_reminder', 'te', 'UTILITY', E'{{1}}: గుర్తుచేస్తున్నాము — {{3}} మీ అద్దె *{{2}}* {{4}}. {{5}}\n\nచెల్లించడానికి *ఇప్పుడే చెల్లించండి* నొక్కండి. ఇప్పటికే చెల్లించారా? ఈ సందేశాన్ని పట్టించుకోకండి.', 5, E'[]'),
  ('rf_reminder', 'ta', 'UTILITY', E'{{1}}: நினைவூட்டல் — {{3}} உங்கள் வாடகை *{{2}}* {{4}}. {{5}}\n\nசெலுத்த *இப்போது செலுத்து* அழுத்துங்கள். ஏற்கனவே செலுத்திவிட்டீர்களா? இந்தச் செய்தியைப் புறக்கணியுங்கள்.', 5, E'[]'),
  ('rf_reminder', 'gu', 'UTILITY', E'{{1}}: યાદ અપાવીએ છીએ — {{3}}નું તમારું ભાડું *{{2}}* {{4}}. {{5}}\n\nચૂકવવા *હમણાં ચૂકવો* દબાવો. ચૂકવી દીધું હોય તો આ સંદેશ અવગણો.', 5, E'[]'),
  ('rf_reminder', 'kn', 'UTILITY', E'{{1}}: ನೆನಪಿಸುತ್ತಿದ್ದೇವೆ — {{3}} ನಿಮ್ಮ ಬಾಡಿಗೆ *{{2}}* {{4}}. {{5}}\n\nಪಾವತಿಸಲು *ಈಗಲೇ ಪಾವತಿಸಿ* ಒತ್ತಿ. ಈಗಾಗಲೇ ಪಾವತಿಸಿದ್ದರೆ ಈ ಸಂದೇಶವನ್ನು ನಿರ್ಲಕ್ಷಿಸಿ.', 5, E'[]'),
  ('rf_reminder', 'ml', 'UTILITY', E'{{1}}: ഓർമ്മപ്പെടുത്തൽ — {{3}} നിങ്ങളുടെ വാടക *{{2}}* {{4}}. {{5}}\n\nഅടയ്ക്കാൻ *ഇപ്പോൾ അടയ്ക്കുക* അമർത്തുക. ഇതിനകം അടച്ചെങ്കിൽ ഈ സന്ദേശം അവഗണിക്കുക.', 5, E'[]'),
  ('rf_reminder', 'pa', 'UTILITY', E'{{1}}: ਯਾਦ ਦਿਵਾਉਣਾ — {{3}} ਦਾ ਤੁਹਾਡਾ ਕਿਰਾਇਆ *{{2}}* {{4}}। {{5}}\n\nਭੁਗਤਾਨ ਲਈ *ਹੁਣੇ ਭੁਗਤਾਨ* ਦਬਾਓ। ਭੁਗਤਾਨ ਕਰ ਦਿੱਤਾ ਹੈ? ਇਸ ਸੁਨੇਹੇ ਨੂੰ ਅਣਡਿੱਠਾ ਕਰੋ।', 5, E'[]'),
  ('rf_reminder', 'ur', 'UTILITY', E'{{1}}: یاد دہانی — {{3}} کا آپ کا کرایہ *{{2}}* {{4}}۔ {{5}}\n\nادائیگی کے لیے *ابھی ادائیگی* دبائیں۔ ادائیگی کر دی ہے؟ اس پیغام کو نظر انداز کریں۔', 5, E'[]'),
  ('rf_payment_received', 'bn', 'UTILITY', E'{{1}}: পেমেন্ট পাওয়া গেছে ✅ {{2}}। রসিদ {{3}} সংযুক্ত। বাকি: {{4}}।\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'mr', 'UTILITY', E'{{1}}: पेमेंट मिळाले ✅ {{2}}. पावती {{3}} जोडली आहे. शिल्लक: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'te', 'UTILITY', E'{{1}}: చెల్లింపు అందింది ✅ {{2}}. రసీదు {{3}} జత చేయబడింది. బాకీ: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'ta', 'UTILITY', E'{{1}}: கட்டணம் கிடைத்தது ✅ {{2}}. ரசீது {{3}} இணைக்கப்பட்டுள்ளது. மீதம்: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'gu', 'UTILITY', E'{{1}}: ચુકવણી મળી ✅ {{2}}. રસીદ {{3}} જોડેલી છે. બાકી: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'kn', 'UTILITY', E'{{1}}: ಪಾವತಿ ಸ್ವೀಕರಿಸಲಾಗಿದೆ ✅ {{2}}. ರಸೀದಿ {{3}} ಲಗತ್ತಿಸಲಾಗಿದೆ. ಬಾಕಿ: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'ml', 'UTILITY', E'{{1}}: പേയ്‌മെന്റ് ലഭിച്ചു ✅ {{2}}. രസീത് {{3}} ചേർത്തിട്ടുണ്ട്. ബാക്കി: {{4}}.\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'pa', 'UTILITY', E'{{1}}: ਭੁਗਤਾਨ ਮਿਲ ਗਿਆ ✅ {{2}}। ਰਸੀਦ {{3}} ਨਾਲ ਲੱਗੀ ਹੈ। ਬਾਕੀ: {{4}}।\n\n{{5}}', 5, E'[]'),
  ('rf_payment_received', 'ur', 'UTILITY', E'{{1}}: ادائیگی موصول ✅ {{2}}۔ رسید {{3}} منسلک ہے۔ باقی: {{4}}۔\n\n{{5}}', 5, E'[]'),
  ('rf_cash_confirm', 'bn', 'UTILITY', E'{{1}}: ম্যানেজার {{2}} {{4}} তারিখে আপনার থেকে {{3}} নগদ নথিভুক্ত করেছেন। এটা কি ঠিক?', 4, E'["ঠিক আছে","ঠিক নয়"]'),
  ('rf_cash_confirm', 'mr', 'UTILITY', E'{{1}}: मॅनेजर {{2}} यांनी {{4}} रोजी तुमच्याकडून {{3}} रोख नोंदवले आहे. हे बरोबर आहे का?', 4, E'["बरोबर","बरोबर नाही"]'),
  ('rf_cash_confirm', 'te', 'UTILITY', E'{{1}}: మేనేజర్ {{2}} {{4}}న మీ నుండి {{3}} నగదు నమోదు చేశారు. ఇది సరైనదేనా?', 4, E'["సరైనది","సరైనది కాదు"]'),
  ('rf_cash_confirm', 'ta', 'UTILITY', E'{{1}}: மேலாளர் {{2}} {{4}} அன்று உங்களிடமிருந்து {{3}} ரொக்கம் பதிவு செய்துள்ளார். இது சரியா?', 4, E'["சரி","சரி இல்லை"]'),
  ('rf_cash_confirm', 'gu', 'UTILITY', E'{{1}}: મેનેજર {{2}}એ {{4}}ના રોજ તમારી પાસેથી {{3}} રોકડ નોંધી છે. શું આ સાચું છે?', 4, E'["સાચું છે","સાચું નથી"]'),
  ('rf_cash_confirm', 'kn', 'UTILITY', E'{{1}}: ಮ್ಯಾನೇಜರ್ {{2}} ಅವರು {{4}} ರಂದು ನಿಮ್ಮಿಂದ {{3}} ನಗದು ದಾಖಲಿಸಿದ್ದಾರೆ. ಇದು ಸರಿಯೇ?', 4, E'["ಸರಿ","ಸರಿಯಲ್ಲ"]'),
  ('rf_cash_confirm', 'ml', 'UTILITY', E'{{1}}: മാനേജർ {{2}} {{4}}-ന് നിങ്ങളിൽ നിന്ന് {{3}} പണമായി രേഖപ്പെടുത്തി. ഇത് ശരിയാണോ?', 4, E'["ശരിയാണ്","ശരിയല്ല"]'),
  ('rf_cash_confirm', 'pa', 'UTILITY', E'{{1}}: ਮੈਨੇਜਰ {{2}} ਨੇ {{4}} ਨੂੰ ਤੁਹਾਡੇ ਤੋਂ {{3}} ਨਕਦ ਦਰਜ ਕੀਤਾ ਹੈ। ਕੀ ਇਹ ਸਹੀ ਹੈ?', 4, E'["ਸਹੀ ਹੈ","ਸਹੀ ਨਹੀਂ"]'),
  ('rf_cash_confirm', 'ur', 'UTILITY', E'{{1}}: مینیجر {{2}} نے {{4}} کو آپ سے {{3}} نقد درج کیا ہے۔ کیا یہ درست ہے؟', 4, E'["درست ہے","درست نہیں"]'),
  ('rf_refund_confirm', 'bn', 'UTILITY', E'{{1}}: আপনার জমার হিসাব — জমা {{2}}, কাটা {{3}}, ফেরত *{{4}}*। আপনি কি ফেরত পেয়েছেন?', 4, E'["পেয়েছি","পাইনি"]'),
  ('rf_refund_confirm', 'mr', 'UTILITY', E'{{1}}: तुमच्या अनामत रकमेचा हिशोब — अनामत {{2}}, कपात {{3}}, परतावा *{{4}}*. तुम्हाला परतावा मिळाला का?', 4, E'["मिळाला","मिळाला नाही"]'),
  ('rf_refund_confirm', 'te', 'UTILITY', E'{{1}}: మీ డిపాజిట్ లెక్క — డిపాజిట్ {{2}}, తగ్గింపులు {{3}}, వాపసు *{{4}}*. మీకు వాపసు అందిందా?', 4, E'["అందింది","అందలేదు"]'),
  ('rf_refund_confirm', 'ta', 'UTILITY', E'{{1}}: உங்கள் வைப்புத்தொகைக் கணக்கு — வைப்பு {{2}}, பிடித்தம் {{3}}, திருப்பித் தருவது *{{4}}*. திருப்பித் தொகை கிடைத்ததா?', 4, E'["கிடைத்தது","கிடைக்கவில்லை"]'),
  ('rf_refund_confirm', 'gu', 'UTILITY', E'{{1}}: તમારી ડિપોઝિટનો હિસાબ — ડિપોઝિટ {{2}}, કપાત {{3}}, પરત *{{4}}*. શું તમને પરત રકમ મળી?', 4, E'["મળી ગઈ","નથી મળી"]'),
  ('rf_refund_confirm', 'kn', 'UTILITY', E'{{1}}: ನಿಮ್ಮ ಠೇವಣಿ ಲೆಕ್ಕ — ಠೇವಣಿ {{2}}, ಕಡಿತ {{3}}, ಹಿಂತಿರುಗಿಸುವುದು *{{4}}*. ನಿಮಗೆ ಹಣ ಹಿಂತಿರುಗಿ ಸಿಕ್ಕಿತೇ?', 4, E'["ಸಿಕ್ಕಿತು","ಸಿಗಲಿಲ್ಲ"]'),
  ('rf_refund_confirm', 'ml', 'UTILITY', E'{{1}}: നിങ്ങളുടെ ഡെപ്പോസിറ്റ് കണക്ക് — ഡെപ്പോസിറ്റ് {{2}}, കിഴിവ് {{3}}, തിരികെ *{{4}}*. തിരികെ തുക ലഭിച്ചോ?', 4, E'["ലഭിച്ചു","ലഭിച്ചില്ല"]'),
  ('rf_refund_confirm', 'pa', 'UTILITY', E'{{1}}: ਤੁਹਾਡੀ ਜਮ੍ਹਾਂ ਰਕਮ ਦਾ ਹਿਸਾਬ — ਜਮ੍ਹਾਂ {{2}}, ਕਟੌਤੀ {{3}}, ਵਾਪਸੀ *{{4}}*। ਕੀ ਤੁਹਾਨੂੰ ਵਾਪਸੀ ਮਿਲ ਗਈ?', 4, E'["ਮਿਲ ਗਈ","ਨਹੀਂ ਮਿਲੀ"]'),
  ('rf_refund_confirm', 'ur', 'UTILITY', E'{{1}}: آپ کی جمع رقم کا حساب — جمع {{2}}، کٹوتی {{3}}، واپسی *{{4}}*۔ کیا آپ کو واپسی مل گئی؟', 4, E'["مل گئی","نہیں ملی"]'),
  ('rf_claim_unmatched', 'bn', 'UTILITY', E'{{1}}: {{2}} তারিখে পাঠানো স্ক্রিনশটের সাথে মেলে এমন কোনো পেমেন্ট এখনও পাইনি। পেমেন্ট করে থাকলে অনুগ্রহ করে UTR / রেফারেন্স নম্বর ম্যানেজারকে দিন।', 2, E'[]'),
  ('rf_claim_unmatched', 'mr', 'UTILITY', E'{{1}}: {{2}} रोजी पाठवलेल्या स्क्रीनशॉटशी जुळणारे पेमेंट अजून मिळालेले नाही. तुम्ही पैसे भरले असल्यास कृपया UTR / रेफरन्स नंबर मॅनेजरला द्या.', 2, E'[]'),
  ('rf_claim_unmatched', 'te', 'UTILITY', E'{{1}}: {{2}}న మీరు పంపిన స్క్రీన్‌షాట్‌కు సరిపోయే చెల్లింపు ఇంకా అందలేదు. మీరు చెల్లించి ఉంటే, దయచేసి UTR / రిఫరెన్స్ నంబర్‌ను మేనేజర్‌కు ఇవ్వండి.', 2, E'[]'),
  ('rf_claim_unmatched', 'ta', 'UTILITY', E'{{1}}: {{2}} அன்று அனுப்பிய ஸ்கிரீன்ஷாட்டுக்குப் பொருந்தும் கட்டணம் இன்னும் வரவில்லை. நீங்கள் செலுத்தியிருந்தால், UTR / குறிப்பு எண்ணை மேலாளரிடம் கொடுங்கள்.', 2, E'[]'),
  ('rf_claim_unmatched', 'gu', 'UTILITY', E'{{1}}: {{2}}ના રોજ મોકલેલા સ્ક્રીનશૉટ સાથે મેળ ખાતી ચુકવણી હજી મળી નથી. જો તમે ચૂકવ્યું હોય, તો કૃપા કરીને UTR / રેફરન્સ નંબર મેનેજરને આપો.', 2, E'[]'),
  ('rf_claim_unmatched', 'kn', 'UTILITY', E'{{1}}: {{2}} ರಂದು ನೀವು ಕಳುಹಿಸಿದ ಸ್ಕ್ರೀನ್‌ಶಾಟ್‌ಗೆ ಹೊಂದುವ ಪಾವತಿ ಇನ್ನೂ ಬಂದಿಲ್ಲ. ನೀವು ಪಾವತಿಸಿದ್ದರೆ, ದಯವಿಟ್ಟು UTR / ರೆಫರೆನ್ಸ್ ನಂಬರ್ ಅನ್ನು ಮ್ಯಾನೇಜರ್‌ಗೆ ನೀಡಿ.', 2, E'[]'),
  ('rf_claim_unmatched', 'ml', 'UTILITY', E'{{1}}: {{2}}-ന് അയച്ച സ്ക്രീൻഷോട്ടിന് ഒത്തുവരുന്ന പേയ്‌മെന്റ് ഇതുവരെ ലഭിച്ചിട്ടില്ല. നിങ്ങൾ അടച്ചെങ്കിൽ, ദയവായി UTR / റഫറൻസ് നമ്പർ മാനേജർക്ക് നൽകുക.', 2, E'[]'),
  ('rf_claim_unmatched', 'pa', 'UTILITY', E'{{1}}: {{2}} ਨੂੰ ਭੇਜੇ ਸਕ੍ਰੀਨਸ਼ਾਟ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਭੁਗਤਾਨ ਅਜੇ ਨਹੀਂ ਮਿਲਿਆ। ਜੇ ਤੁਸੀਂ ਭੁਗਤਾਨ ਕੀਤਾ ਹੈ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ UTR / ਰੈਫਰੈਂਸ ਨੰਬਰ ਮੈਨੇਜਰ ਨੂੰ ਦਿਓ।', 2, E'[]'),
  ('rf_claim_unmatched', 'ur', 'UTILITY', E'{{1}}: {{2}} کو بھیجے گئے اسکرین شاٹ سے ملتی ادائیگی ابھی تک نہیں ملی۔ اگر آپ نے ادائیگی کی ہے تو براہ کرم UTR / ریفرنس نمبر مینیجر کو دیں۔', 2, E'[]'),
